sys_ux_client_script.script:
/**
  * @param {params} params
  * @param {api} params.api
  * @param {TransformApiHelpers} params.helpers
  */
function evaluateProperty({api, helpers}) {
    // Get the data from api.data.dynamic_sys_reader_1.output
    const data = api.data.dynamic_sys_reader_1.output;

    // Filter the data to return only items where the value is "saas" and complex is true
    const filteredData = data.filter(item => item.type === "saas" && item.complex === true);

    // Return the filtered data
    return filteredData;
}
